/**
 * S9-2 档位管理面板：向导预检步内增改档位，直写 pao配置/档位.json。
 * 编辑对象下拉选现有档＝改（原名进 editing）；「新建档位」＝追加（重名由内核拒绝）。
 * provider/model 手输斜杠合写（与 fork /pao model 手输后门同口径）；
 * 保存成功后由父层刷新目录，新档位立刻进主控档位下拉（对已运行会话需重开会话生效）。
 */
export function TierManagerPanel({
  tiers,
  thinkingLevels,
  disabled,
  onSave,
}: {
  readonly tiers: readonly WizardTier[];
  readonly thinkingLevels: readonly string[];
  readonly disabled: boolean;
  readonly onSave: (input: WorkflowTierSaveInput) => Promise<WorkflowMutationResult>;
}) {
  const { t } = useI18n();
  const [editing, setEditing] = useState("");
  const [name, setName] = useState("");
  const [providerModel, setProviderModel] = useState("");
  const [thinkingLevel, setThinkingLevel] = useState("");
  const [status, setStatus] = useState("");
  const [saving, setSaving] = useState(false);

  const pickTier = (value: string) => {
    setEditing(value);
    const tier = tiers.find((entry) => entry.name === value);
    setName(tier?.name ?? "");
    setProviderModel(tier ? `${tier.provider}/${tier.model}` : "");
    setThinkingLevel(tier?.thinkingLevel ?? "");
    setStatus("");
  };

  const save = async () => {
    const [provider, model] = providerModel.trim().split("/");
    if (!name.trim() || !provider?.trim() || !model?.trim() || !thinkingLevel) {
      setStatus(t("Fill in the tier name, provider/model and thinking level."));
      return;
    }
    setSaving(true);
    setStatus("");
    try {
      const result = await onSave({
        tier: { name: name.trim(), provider: provider.trim(), model: model.trim(), thinkingLevel },
        ...(editing ? { editing } : {}),
      });
      if (result.state === "error") {
        setStatus(result.message);
        return;
      }
      // 先清表单再设状态：pickTier 会 setStatus("")，顺序反了会把成功提示清掉。
      pickTier("");
      setStatus(t("Tier saved."));
    } catch (cause) {
      setStatus(cause instanceof Error ? cause.message : String(cause));
    } finally {
      setSaving(false);
    }
  };

  return (
    <fieldset className="wizard-node" data-testid="wizard-tier-manager">
      <legend>{t("Manage tiers")}</legend>
      <label className="wizard-field">
        <span>{t("Edit tier")}</span>
        <select
          data-testid="wizard-tier-picker"
          onChange={(event) => pickTier(event.target.value)}
          value={editing}
        >
          <option value="">{t("New tier")}</option>
          {tiers.map((tier) => (
            <option key={tier.name} value={tier.name}>
              {tier.name} ({tier.provider}/{tier.model})
            </option>
          ))}
        </select>
      </label>
      <label className="wizard-field">
        <span>{t("Tier name")}</span>
        <input
          data-testid="wizard-tier-name"
          onChange={(event) => setName(event.target.value)}
          type="text"
          value={name}
        />
      </label>
      <label className="wizard-field">
        <span>{t("Physical model (provider/model)")}</span>
        <input
          data-testid="wizard-tier-model"
          placeholder="zai-coding-cn/glm-5.3"
          onChange={(event) => setProviderModel(event.target.value)}
          type="text"
          value={providerModel}
        />
      </label>
      <label className="wizard-field">
        <span>{t("Recommended thinking level")}</span>
        <select
          data-testid="wizard-tier-thinking"
          onChange={(event) => setThinkingLevel(event.target.value)}
          value={thinkingLevel}
        >
          <option value="">{t("Select a level")}</option>
          {thinkingLevels.map((value) => (
            <option key={value} value={value}>
              {value}
            </option>
          ))}
        </select>
      </label>
      <div className="wizard-actions">
        <button
          className="button"
          data-testid="wizard-tier-save"
          disabled={disabled || saving}
          type="button"
          onClick={() => {
            void save();
          }}
        >
          {t("Save tier")}
        </button>
      </div>
      {status ? (
        <p className="wizard-hint" data-testid="wizard-tier-status">
          {status}
        </p>
      ) : null}
      <p className="wizard-hint">
        {t("Writes pao配置/档位.json with an automatic backup; new tiers apply to new sessions.")}
      </p>
    </fieldset>
  );
}

import { useMemo, useSyncExternalStore } from "react";
import type {
  SessionRecord,
  SessionStatus,
  WorkspaceSessionTarget,
} from "../../../../contracts/desktop-state";
import type {
  PiDesktopApi,
  SessionControlAction,
  SessionControlResponse,
} from "../../../../contracts/ipc";
import {
  deriveThreadControlState,
  type ThreadControlState,
} from "../../../../contracts/thread-control-state";

/**
 * 渲染层控制入口客户端（设计包-控制入口五态-2026-10-04 §2.3）。
 *
 * - 每个请求带渲染层生成的 requestId（uuid）；本地留一份回执账，供五态推导与查证恢复。
 * - invoke 超时/异常后先 `query(requestId)` 查主进程账，再决定；查到已受理/已完成就
 *   采用该账（不盲重发），查不到（账丢失）按失败上报，由调用方以 state 重建视图。
 * - 回执账只存内存（与主进程账同命）：重启即「未知」，以文件/驱动真相重建（拍板 §6.4）。
 */

export interface SessionControlReceipt {
  readonly requestId: string;
  readonly kind: SessionControlAction["kind"];
  readonly accepted: boolean;
  /** 主进程账已定（done/rejected，或查证后落定）。 */
  readonly done: boolean;
  readonly reason?: string;
  readonly at: number;
}

const MAX_RECEIPTS_PER_SESSION = 32;

const receiptsBySession = new Map<string, SessionControlReceipt[]>();
const listeners = new Set<() => void>();
let version = 0;

function emitChange(): void {
  version += 1;
  for (const listener of [...listeners]) listener();
}

function noteReceipt(sessionId: string, receipt: SessionControlReceipt): void {
  const receipts = receiptsBySession.get(sessionId) ?? [];
  receipts.push(receipt);
  if (receipts.length > MAX_RECEIPTS_PER_SESSION) receipts.shift();
  receiptsBySession.set(sessionId, receipts);
  emitChange();
}

function subscribe(listener: () => void): () => void {
  listeners.add(listener);
  return () => {
    listeners.delete(listener);
  };
}

function getVersion(): number {
  return version;
}

function latestReceipt(
  sessionId: string,
  kind: SessionControlAction["kind"],
): SessionControlReceipt | undefined {
  const receipts = receiptsBySession.get(sessionId);
  if (!receipts) return undefined;
  for (let index = receipts.length - 1; index >= 0; index--) {
    if (receipts[index]?.kind === kind) return receipts[index];
  }
  return undefined;
}

/**
 * 单一控制入口调用：带 requestId、留回执账；失败先查账再落定，不盲重发。
 * 返回主进程回执（含 controlState 与全量 state）。
 */
export async function sendSessionControl(
  api: PiDesktopApi,
  sessionId: string,
  target: WorkspaceSessionTarget,
  action: SessionControlAction,
): Promise<SessionControlResponse> {
  const requestId = crypto.randomUUID();
  noteReceipt(sessionId, {
    requestId,
    kind: action.kind,
    accepted: true,
    done: false,
    at: Date.now(),
  });
  try {
    const response = await api.sessionControl({ target, requestId, action });
    noteReceipt(sessionId, {
      requestId,
      kind: action.kind,
      accepted: response.accepted,
      done: true,
      ...(response.reason ? { reason: response.reason } : {}),
      at: Date.now(),
    });
    return response;
  } catch (error) {
    // invoke 超时/异常（§2.3）：先 query 查账，不盲重发。查到已受理/已完成 → 采用该账；
    // 账丢失/查询也失败 → 按原始失败落定，由调用方用文件/驱动真相重建视图。
    try {
      const probe = await api.sessionControl({
        target,
        requestId,
        action: { kind: "query", requestId },
      });
      noteReceipt(sessionId, {
        requestId,
        kind: action.kind,
        accepted: probe.accepted,
        done: true,
        ...(probe.reason ? { reason: probe.reason } : {}),
        at: Date.now(),
      });
      return probe;
    } catch {
      noteReceipt(sessionId, {
        requestId,
        kind: action.kind,
        accepted: false,
        done: true,
        reason: error instanceof Error ? error.message : String(error),
        at: Date.now(),
      });
      throw error;
    }
  }
}

export interface ThreadControlView {
  readonly state: ThreadControlState | null;
  /** 最近一次取消回执的发起时刻（epoch ms）；「停止中时间较长」提示用。 */
  readonly cancelRequestedAt: number | undefined;
}

/**
 * 五态视图：把 (SessionStatus, 未决取消, cancelRequestId 匹配, send 受理) 与本地回执账
 * 合成后交给 contracts/thread-control-state.ts 的表驱动纯函数。PAO 卡路径投影本批不接
 * （桌面零写卡，卡面真相由看板批次展示），普通会话不出现「验收通过」。
 */
export function deriveThreadControlView(
  sessionId: string | undefined,
  session: { readonly status: SessionStatus; readonly cancellationRequested?: boolean } | undefined,
): ThreadControlView {
  const lastCancel = sessionId ? latestReceipt(sessionId, "cancel") : undefined;
  const lastSend = sessionId ? latestReceipt(sessionId, "send") : undefined;
  const state = deriveThreadControlState({
    status: session?.status ?? "idle",
    // 在途回执（驱动尚未广播 stopping 前）也算未决取消。
    cancellationRequested:
      session?.cancellationRequested === true || (lastCancel !== undefined && !lastCancel.done),
    cancelRequestIdMatched: lastCancel?.done === true && lastCancel.accepted === true,
    sendAcceptedPendingRun: lastSend !== undefined && lastSend.accepted && !lastSend.done,
  });
  return { state, cancelRequestedAt: lastCancel?.at };
}

/** React 绑定：回执账变化时重算五态视图。 */
export function useThreadControlView(
  sessionId: string | undefined,
  session: Pick<SessionRecord, "status" | "cancellationRequested"> | undefined,
): ThreadControlView {
  const currentVersion = useSyncExternalStore(subscribe, getVersion);
  return useMemo(
    () => deriveThreadControlView(sessionId, session),
    // eslint-disable-next-line react-hooks/exhaustive-deps -- version 门槛：回执账变化即重算
    [currentVersion, sessionId, session?.status, session?.cancellationRequested],
  );
}

