  taskRoot: string;
  executionRoot: string;
  worktreeId: string;
  snapshotDigest: string;
  worktreeBindingDigest: string;
  executionBindingDigest: string;
  cardPath: string;
  attempt: number;
  cardNo: number;
  start: number;
  barrierReleased: number;
  end: number;
