      isError: false,
      ...(index < 2
        ? {
            details: {
              binding: {
                kind: "managed",
                worktreeId: index ? "tree-b" : "tree-a",
                executionRoot: index ? "root-b" : "root-a",
              },
            },
          }
        : {}),
