          映射状态: "运行中",
          会话路径: "/p/s1.jsonl",
          时间: "t1",
          来源: "执行映射",
        },
        { 映射状态: "无标识坏行" }, // 坏行剔除
        { 执行标识: "exec-2", 来源: "卡回执" },
      ],
      升档理由: "升档：两轮打回后提到高配",
