    expect(html).toContain("exec-1");
    expect(html).toContain('data-testid="canvas-detail-open-session"');
  });

  test("批1/批2 折叠分区：八区入口齐且会话/监督按规格排序；回执只在「回执轮次」渲染一次", () => {
    const html = renderBody({
      node: "实现",
      instance: "/p/i",
      card: {
        cardRef: "卡0001",
        status: "delivered",
        attempts: 1,
        created: "2026-10-05 10:00",
        path: "/p/卡/卡0001.md",
        receipts: [
          {
            attempt: 1,
            time: "2026-10-05 10:30",
            result: "打回",
            failureType: "验收不通过",
            summary: "缺测试",
            evidence: ["src/a.ts:12"],
            artifacts: ["src/a.ts"],
          },
