      "basics",
      "session",
      "io",
      "receipts",
      "artifacts",
      "usage",
      "logs",
      "supervision",
    ]) {
      expect(html).toContain(`data-testid="canvas-section-${section}"`);
    }
    expect(html.indexOf('data-testid="canvas-section-session"')).toBeLessThan(
      html.indexOf('data-testid="canvas-section-io"'),
    );
    expect(html.indexOf('data-testid="canvas-section-supervision"')).toBeGreaterThan(
      html.indexOf('data-testid="canvas-section-logs"'),
    );
    // 批3a 注入分区：有注入 props 时排在「监督」之后（L91 顺序）；无 props 时不渲染。
    const withInjection = renderBody(
      {
        node: "实现",
        instance: "/p/i",
        card: {
          cardRef: "卡0001",
          status: "delivered",
          attempts: 1,
