          options: [{ kind: "owner", label: "owner own-1" }],
          target: { kind: "owner" },
          text: "",
        },
      },
    );
    expect(withInjection).toContain('data-testid="canvas-section-injection"');
    expect(withInjection.indexOf('data-testid="canvas-section-injection"')).toBeGreaterThan(
      withInjection.indexOf('data-testid="canvas-section-supervision"'),
    );
    expect(html).not.toContain('data-testid="canvas-section-injection"');
    // 回执唯一入口：rounds 列表只挂一个分区，回执内容（摘要/失败类型）不重复出现在别处
    expect(html.match(/data-testid="canvas-detail-rounds"/g)).toHaveLength(1);
    expect(html.match(/缺测试/g)).toHaveLength(1);
    expect(html.match(/验收不通过/g)).toHaveLength(1);
    // 产物独立分区：来自回执 artifacts，标注来源 attempt
    expect(html).toContain('data-testid="canvas-detail-artifacts"');
    expect(html).toContain("src/a.ts");
    expect(html).toContain("from attempt");
  });

  test("未落卡：查看卡禁用＋「Not on a card yet」；错误行透出", () => {
    const html = renderBody({
      node: "复核",
      instance: "/p/i",
