describe("批3a 注入目标解析（canvasInjectionPlan）", () => {
  const node = {
    name: "实现",
    dept: "工程",
    dependsOn: [] as string[],
    requiresConfirmation: false,
    ministerSessionId: "minister-1",
    round: 2,
    executionMode: "拆解" as const,
  };

  test("唯一在途 worker 默认；顺位 worker→minister→owner", () => {
    const detail = {
      node: "实现",
      instance: "/p/i",
      executions: [
        { execId: "exec-run", source: "执行映射", status: "运行中", attempt: 2, current: true },
        { execId: "exec-old", source: "执行映射", status: "成功", attempt: 1, current: false },
      ],
    };
    const plan = canvasInjectionPlan({ detail, node, ownerSessionId: "own-1" });
    // 三个目标全列出；默认＝唯一在途 worker。
    expect(plan.options.map((option) => option.kind)).toEqual(["worker", "minister", "owner"]);
    expect(plan.target).toEqual({ kind: "worker", executionId: "exec-run" });
    expect(plan.workerNeedsPick).toBe(false);
    expect(plan.options[0]?.label).toContain("exec-run");
    expect(plan.options[0]?.label).toContain("attempt 2");
  });

  test("多个在途 worker 全列出且 needsPick；显式选中不在在途集内回落顺位", () => {
    const detail = {
      node: "实现",
      instance: "/p/i",
      executions: [
        { execId: "exec-a", source: "执行映射", status: "运行中", attempt: 2, current: true },
        { execId: "exec-b", source: "执行映射", status: "运行中", attempt: 3, current: false },
      ],
    };
    const plan = canvasInjectionPlan({ detail, node, ownerSessionId: "own-1" });
    expect(plan.workerNeedsPick).toBe(true);
    expect(plan.options.filter((option) => option.kind === "worker")).toHaveLength(2);
    // 显式选中 exec-b 生效（更新目标标识）；选中已失效的执行回落顺位第一项。
    const picked = canvasInjectionPlan({
      detail,
      node,
      ownerSessionId: "own-1",
      selected: { kind: "worker", executionId: "exec-b" },
    });
    expect(picked.target).toEqual({ kind: "worker", executionId: "exec-b" });
    const stale = canvasInjectionPlan({
      detail,
      node,
      ownerSessionId: "own-1",
      selected: { kind: "worker", executionId: "exec-gone" },
    });
    expect(stale.target.kind).toBe("worker");
    expect(stale.target.executionId).toBe("exec-a");
  });

  test("无在途 worker→部长；无部长→owner；脚本节点只留 owner", () => {
    const noWorker = {
      node: "实现",
      instance: "/p/i",
      executions: [{ execId: "exec-old", source: "执行映射", status: "成功", attempt: 1 }],
    };
    const minister = canvasInjectionPlan({ detail: noWorker, node, ownerSessionId: "own-1" });
    expect(minister.target).toEqual({ kind: "minister" });
    // 部长未绑定→owner。
    const unbound = canvasInjectionPlan({
      detail: noWorker,
      node: { ...node, ministerSessionId: undefined },
      ownerSessionId: "own-1",
    });
    expect(unbound.target).toEqual({ kind: "owner" });
    // 脚本节点不提供 worker/minister（L168）：即便在途锚点存在也不列。
    const script = canvasInjectionPlan({
      detail: {
        node: "实现",
        instance: "/p/i",
        executions: [
          { execId: "exec-run", source: "执行映射", status: "运行中", attempt: 1, current: true },
        ],
      },
      node: { ...node, executionMode: "脚本" as const },
      ownerSessionId: "own-1",
    });
    expect(script.options.map((option) => option.kind)).toEqual(["owner"]);
    expect(script.target).toEqual({ kind: "owner" });
  });

