describe("批3a 注入命令组装（canvasInjectionCommand）", () => {
  const base = {
    workspaceId: "ws-a",
    sessionId: "s-owner",
    instanceId: "ins-1",
    nodeName: "实现",
    round: 2,
    text: "补一段说明",
  };

  test("owner 目标不携带 nodeName/round（契约禁止伪造节点关联）", () => {
    const result = canvasInjectionCommand({ ...base, target: { kind: "owner" } });
    expect(result.block).toBeUndefined();
    expect(result.command).toEqual({
      workspaceId: "ws-a",
      sessionId: "s-owner",
      instanceId: "ins-1",
      action: "inject",
      target: "owner",
      text: "补一段说明",
    });
    expect(result.command).not.toHaveProperty("nodeName");
    expect(result.command).not.toHaveProperty("round");
  });

  test("minister 目标携带 nodeName+round；round 缺省本地拦截不发 0", () => {
    const result = canvasInjectionCommand({ ...base, target: { kind: "minister" } });
    expect(result.block).toBeUndefined();
    expect(result.command).toMatchObject({ nodeName: "实现", round: 2, target: "minister" });
    expect(result.command).not.toHaveProperty("cardRef");
    expect(result.command).not.toHaveProperty("executionId");
    // round 缺省是真实缺数据：拦在本地，不发 0 让 decoder 拒成 unknown（M1）。
    const noRound = canvasInjectionCommand({
      ...base,
      round: undefined,
      target: { kind: "minister" },
    });
    expect(noRound.command).toBeUndefined();
    expect(noRound.block).toContain("round is not bound");
  });

  test("worker 目标携带全锚点；缺 executionId/cardRef/attempt 分别本地拦截", () => {
    const worker = canvasInjectionCommand({
      ...base,
      target: { kind: "worker", executionId: "exec-1" },
      cardRef: "卡0007",
      attempt: 3,
    });
    expect(worker.block).toBeUndefined();
    expect(worker.command).toMatchObject({
      nodeName: "实现",
      round: 2,
      target: "worker",
      cardRef: "卡0007",
      executionId: "exec-1",
      attempt: 3,
    });
    // 缺执行标识。
    expect(
      canvasInjectionCommand({ ...base, target: { kind: "worker" }, cardRef: "卡0007", attempt: 3 })
        .block,
    ).toContain("worker execution anchor is missing");
    // 缺卡引用。
    expect(
      canvasInjectionCommand({
        ...base,
        target: { kind: "worker", executionId: "exec-1" },
        attempt: 3,
      }).block,
    ).toContain("card reference");
    // 缺尝试号。
    expect(
      canvasInjectionCommand({
        ...base,
        target: { kind: "worker", executionId: "exec-1" },
        cardRef: "卡0007",
      }).block,
    ).toContain("attempt number");
    // worker 缺 round 也拦在本地。
    expect(
      canvasInjectionCommand({
        ...base,
        round: undefined,
        target: { kind: "worker", executionId: "exec-1" },
        cardRef: "卡0007",
        attempt: 3,
      }).block,
    ).toContain("round is not bound");
  });
});

describe("批3a 注入分区渲染（renderToString）", () => {
  const node = {
