            { kind: "owner", label: "owner own-1" },
          ],
          target: { kind: "worker", executionId: "exec-a" },
          text: "",
        },
      }),
    );
    expect(multi).toContain('data-testid="canvas-injection-targets"');
    expect(multi).toContain("worker exec-a · attempt 2");
    expect(multi).toContain("minister minister-1");
    expect(multi).toContain("owner own-1");
    // 单目标无选择器，只显示目标行。
    const single = renderToString(
      createElement(NodeRuntimeDetails, {
        node,
        hasDetail: true,
        expanded: { ...initialDetailSections(node), injection: true },
        injection: {
          options: [{ kind: "owner", label: "owner own-1" }],
          target: { kind: "owner" },
          text: "",
        },
      }),
    );
    expect(single).not.toContain('data-testid="canvas-injection-targets"');
    expect(single).toContain('data-testid="canvas-injection-target"');
    expect(single).toContain("owner own-1");
  });

  test("发送在途禁用；blockReason 显示且禁用；结果分支渲染", () => {
    const sending = renderToString(
      createElement(NodeRuntimeDetails, {
        node,
        hasDetail: true,
        expanded: { ...initialDetailSections(node), injection: true },
        injection: {
          options: [{ kind: "owner", label: "owner own-1" }],
          target: { kind: "owner" },
