    // blockReason 显示且禁用（空正文不发）。
    const blocked = renderToString(
      createElement(NodeRuntimeDetails, {
        node,
        hasDetail: true,
        expanded: { ...initialDetailSections(node), injection: true },
        injection: {
          options: [{ kind: "owner", label: "owner own-1" }],
          target: { kind: "owner" },
          text: "",
          blockReason: "Write the message to inject first.",
        },
      }),
    );
    expect(blocked).toContain('data-testid="canvas-injection-block"');
    expect(blocked).toMatch(/canvas-injection-send[^>]*disabled/);
    // 结果分支：refused 用 error＋role=alert；delivered 用 note。
    const refused = renderToString(
      createElement(NodeRuntimeDetails, {
        node,
        hasDetail: true,
        expanded: { ...initialDetailSections(node), injection: true },
        injection: {
          options: [{ kind: "owner", label: "owner own-1" }],
          target: { kind: "owner" },
          text: "正文",
          result: { kind: "refused", message: "轮次已变化" },
        },
      }),
    );
    expect(refused).toContain('data-testid="canvas-injection-result-refused"');
    expect(refused).toContain('role="alert"');
    expect(refused).toContain("轮次已变化");
    const delivered = renderToString(
      createElement(NodeRuntimeDetails, {
        node,
        hasDetail: true,
        expanded: { ...initialDetailSections(node), injection: true },
        injection: {
          options: [{ kind: "owner", label: "owner own-1" }],
          target: { kind: "owner" },
          text: "",
          result: { kind: "delivered" },
        },
      }),
    );
    expect(delivered).toContain('data-testid="canvas-injection-result-delivered"');
    expect(delivered).toContain("does not mean it was executed");
  });
});

