describe("canvasDetailFetchPlan（批1 详情懒加载判定）", () => {
  const base = {
    fetchable: true,
    deepOpen: false,
    logsOpen: false,
    detailLoaded: false,
    statsLoaded: false,
    inFlight: false,
  };

  test("纯选中（仅基本区开）不拉；不可发请求不拉", () => {
    expect(canvasDetailFetchPlan(base)).toEqual({ action: "skip" });
    expect(canvasDetailFetchPlan({ ...base, fetchable: false, deepOpen: true })).toEqual({
      action: "skip",
    });
  });

  test("任一详情分区展开且未拉 → fetch；同键已拉 → skip；在途 → wait", () => {
    expect(canvasDetailFetchPlan({ ...base, deepOpen: true })).toEqual({ action: "fetch" });
    expect(canvasDetailFetchPlan({ ...base, deepOpen: true, detailLoaded: true })).toEqual({
      action: "skip",
    });
    expect(canvasDetailFetchPlan({ ...base, deepOpen: true, inFlight: true })).toEqual({
      action: "wait",
    });
    // 已拉详情且 logs 区未开：折叠态变化不重读
    expect(
      canvasDetailFetchPlan({ ...base, deepOpen: true, detailLoaded: true, statsLoaded: false }),
    ).toEqual({ action: "skip" });
  });

  test("失败后 detailLoaded=false 再进判定仍 fetch（非永久 skip）", () => {
    // 失败路径：组件不置 detailLoaded（detail 未到），重试经 retryNonce 重新进判定。
    // 纯函数只认 detailLoaded——false 即视为未拉成功，可再次 fetch，不会锁死。
    const failedOnce = { ...base, deepOpen: true, detailLoaded: false };
    expect(canvasDetailFetchPlan(failedOnce)).toEqual({ action: "fetch" });
    // 失败但有旧 detail（同键重拉失败保留旧值）：detailLoaded=true → skip，
    // 只有手动重试计数变化才重新进入判定（组件层职责，非本函数）。
    expect(canvasDetailFetchPlan({ ...base, deepOpen: true, detailLoaded: true })).toEqual({
      action: "skip",
    });
  });

  test("logs 区展开 → 已拉详情时带 includeSessionStats 补读；首拉顺带统计", () => {
    // 详情已读、logs 首开：第二趟带 stats 重拉（整体替换缓存）
    expect(
      canvasDetailFetchPlan({ ...base, deepOpen: true, logsOpen: true, detailLoaded: true }),
    ).toEqual({ action: "fetch", includeSessionStats: true });
    // 首趟时 logs 已开：同一请求顺带统计，比落地后补一趟便宜
    expect(canvasDetailFetchPlan({ ...base, deepOpen: true, logsOpen: true })).toEqual({
      action: "fetch",
      includeSessionStats: true,
    });
    // stats 已含 → 不再重读
    expect(
      canvasDetailFetchPlan({
        ...base,
        deepOpen: true,
        logsOpen: true,
        detailLoaded: true,
        statsLoaded: true,
      }),
    ).toEqual({ action: "skip" });
    // 在途不重发（落地后由依赖变化再判定）
    expect(
      canvasDetailFetchPlan({
        ...base,
        deepOpen: true,
        logsOpen: true,
        detailLoaded: true,
        inFlight: true,
      }),
    ).toEqual({ action: "wait" });
  });
});

