describe("readNodeDetail 的 sessionStats 拆分（includeSessionStats!==true 跳过日志扫描）", () => {
  async function realDir(): Promise<string> {
    const { mkdtemp } = await import("node:fs/promises");
    const { tmpdir } = await import("node:os");
    const { join } = await import("node:path");
    return mkdtemp(join(tmpdir(), "pi-gui-canvas-stats-"));
  }

  /** 注入含一条执行映射的运行态读取器；scanCalls 记录日志增量扫描次数。 */
  function runtimeReader(scanCalls: number[]): PaoDesktopRuntimeReader {
    return {
      readDesktopProject: async (root: string) => ({
        projectRoot: root,
        cards: [
          {
            path: `${root}/.pao/卡/卡0001.md`,
            filename: "卡0001.md",
            card_no: 1,
            frontmatter: { attempt: 1, created: "2026-10-05 10:00", status: "in_progress" },
            body: "",
            receipts: [],
          },
        ],
        execution: [
          {
            执行标识: "exec-1",
            卡路径: `${root}/.pao/卡/卡0001.md`,
            尝试: 1,
            状态: "运行中",
            映射路径: `${root}/.pao/执行映射/exec-1.jsonl`,
            会话路径: `${root}/.pao/worker会话/s_exec-1.jsonl`,
            当前尝试: true,
          },
        ],
        issues: [],
      }),
      readDesktopSessionIncrement: (session: string) => {
        scanCalls.push(1);
        return {
          会话路径: session,
          下次偏移: 12,
          末行未完: false,
          还有更多: false,
          行: [],
          本段统计: { 响应: 2, 工具: 1, token: 300, 未知用量: 0 },
        };
      },
    };
  }

  function detailReaderFor(cardPath: string): PaoDesktopNodeDetailReader {
    return (_h, i, n) => ({
      节点: n,
      实例: i,
      卡: {
        卡号: "卡0001",
        状态: "in_progress",
        尝试: 1,
        创建: "2026-10-05 10:00",
        路径: cardPath,
        回执: [],
      },
      执行: [],
    });
  }

  test("默认调用不扫会话日志；sessionStats 留空", async () => {
    const { realpath } = await import("node:fs/promises");
    const { join } = await import("node:path");
    const home = await realpath(await realDir());
    const scanCalls: number[] = [];
    const query = createCanvasQuery({
      paoHome: home,
      loadDetailReader: async () => detailReaderFor(join(home, ".pao", "卡", "卡0001.md")),
      loadRuntimeReader: async () => runtimeReader(scanCalls),
    });
    const result = await query.readNodeDetail(join(home, ".pao", "工作流实例-好流.md"), "实现");
    expect(result.state).toBe("ok");
    expect(scanCalls).toHaveLength(0);
    if (result.state !== "ok") throw new Error("unreachable");
    const exec = result.detail.executions.find((item) => item.execId === "exec-1");
    expect(exec).toBeDefined();
    expect(exec?.sessionStats).toBeUndefined();
    expect(exec?.statsError).toBeUndefined();
  });

  test("includeSessionStats:true 才扫描并回填 sessionStats", async () => {
    const { realpath } = await import("node:fs/promises");
    const { join } = await import("node:path");
    const home = await realpath(await realDir());
    const scanCalls: number[] = [];
    const query = createCanvasQuery({
      paoHome: home,
      loadDetailReader: async () => detailReaderFor(join(home, ".pao", "卡", "卡0001.md")),
      loadRuntimeReader: async () => runtimeReader(scanCalls),
    });
    const result = await query.readNodeDetail(
      join(home, ".pao", "工作流实例-好流.md"),
      "实现",
      undefined,
      {
        includeSessionStats: true,
      },
    );
    expect(result.state).toBe("ok");
    expect(scanCalls).toHaveLength(1);
    if (result.state !== "ok") throw new Error("unreachable");
    expect(
      result.detail.executions.find((item) => item.execId === "exec-1")?.sessionStats?.tokens,
    ).toBe(300);
  });
});

describe("批2p 产物媒体预览（片C）", () => {
  test("artifactPreviewView：mediaKind→元素分支映射", () => {
    // image/video 拼 data: URI；text 走正文+截断标记；other 不预览
    expect(
      artifactPreviewView({
        state: "ok",
        displayPath: "/p/out.png",
        mediaKind: "image",
        mime: "image/png",
        sizeBytes: 3,
        dataBase64: "aGk=",
      }),
    ).toEqual({ kind: "image", src: "data:image/png;base64,aGk=", displayPath: "/p/out.png" });
    expect(
      artifactPreviewView({
        state: "ok",
        displayPath: "/p/v.webm",
        mediaKind: "video",
        mime: "video/webm",
        sizeBytes: 3,
        dataBase64: "aGk=",
      }),
    ).toEqual({ kind: "video", src: "data:video/webm;base64,aGk=", displayPath: "/p/v.webm" });
    expect(
      artifactPreviewView({
        state: "ok",
        displayPath: "/p/t.txt",
        mediaKind: "text",
        mime: "text/plain",
        sizeBytes: 3,
        text: "hello",
        truncated: true,
      }),
    ).toEqual({ kind: "text", text: "hello", truncated: true });
    expect(
      artifactPreviewView({
        state: "ok",
        displayPath: "/p/b.bin",
        mediaKind: "other",
        mime: "application/octet-stream",
        sizeBytes: 7,
      }),
    ).toEqual({ kind: "other", displayPath: "/p/b.bin", sizeBytes: 7 });
    // image 无载荷 → undecodable 兜底，不渲空 src
    expect(
      artifactPreviewView({
        state: "ok",
        displayPath: "/p/x.png",
        mediaKind: "image",
        mime: "image/png",
        sizeBytes: 0,
      }),
    ).toEqual({ kind: "failed", code: "undecodable", message: "" });
  });

  test("失败 code → 文案键：too-large 带打开入口语义，not-in-receipt/out-of-root 分别有因", () => {
    for (const code of [
      "not-in-receipt",
      "missing",
      "out-of-root",
      "symlink",
      "permission-denied",
      "too-large",
      "unsupported",
      "undecodable",
      "read-error",
    ] as const) {
      expect(artifactFailureLabelKey(code)).toBeTruthy();
    }
    expect(artifactFailureLabelKey("too-large")).toContain("too large");
    expect(artifactFailureLabelKey("not-in-receipt")).toContain("not declared");
    // failed 载荷经 artifactPreviewView 也走 failed 分支并带 sizeBytes
    expect(
      artifactPreviewView({
        state: "failed",
        code: "too-large",
        message: "22 MiB",
        sizeBytes: 22 * 1024 * 1024,
      }),
    ).toEqual({
      kind: "failed",
      code: "too-large",
      message: "22 MiB",
      sizeBytes: 22 * 1024 * 1024,
    });
