        可用: true,
        解释器: "C:/Program Files/PowerShell/7/pwsh.exe",
        种类: "pwsh",
      }),
    });
    const result = await query.readScriptInterpreter();
    expect(result).toEqual({
      available: true,
      interpreter: "C:/Program Files/PowerShell/7/pwsh.exe",
      kind: "pwsh",
    });
  });

  test("powershell.exe 回退＝kind:powershell；探测失败/加载失败落 available:false", async () => {
    const fallback = createCanvasQuery({
      paoHome: "/p",
      loadScriptInterpreter: async () => () => ({
        可用: true,
        解释器: "C:/Windows/System32/powershell.exe",
        种类: "powershell",
      }),
    });
    expect(await fallback.readScriptInterpreter()).toEqual({
      available: true,
      interpreter: "C:/Windows/System32/powershell.exe",
      kind: "powershell",
    });
    const missing = createCanvasQuery({
      paoHome: "/p",
      loadScriptInterpreter: async () => () => ({ 可用: false, 原因: "未装 PowerShell" }),
    });
    expect(await missing.readScriptInterpreter()).toEqual({
      available: false,
      reason: "未装 PowerShell",
    });
    const boom = createCanvasQuery({
      paoHome: "/p",
      loadScriptInterpreter: async () => {
