});

describe("批3b-U 脚本分区渲染（renderToString）", () => {
  function renderScript(
    detail: Parameters<typeof CanvasNodeDetailBody>[0]["detail"],
    script: Parameters<typeof CanvasNodeDetailBody>[0]["script"],
    extra: Partial<Parameters<typeof CanvasNodeDetailBody>[0]> = {},
  ): string {
    return renderToString(
      createElement(CanvasNodeDetailBody, {
        detail,
        script,
        onOpenCard: () => undefined,
        onOpenSession: () => undefined,
        session: { input: null, reason: "no-anchor" },
        supervision: { status: "unbound" },
        ...extra,
      }),
    );
  }

  const scriptCard = {
    cardRef: "卡0001",
    status: "delivered",
    attempts: 1,
    created: "2026-10-05 10:00",
    path: "/p/卡/卡0001.md",
    receipts: [],
  };

  test("脚本节点：冻结正文/超时/声明产物＋冻结标注＋解释器", () => {
    const html = renderScript(
      {
        node: "跑脚本",
        instance: "/p/i",
        card: {
          ...scriptCard,
          script: "Write-Output hi",
          scriptTimeout: 120,
          scriptArtifacts: ["out/a.txt"],
        },
        executions: [],
      },
      {
        applicable: true,
        interpreter: {
          available: true,
          interpreter: "C:/Program Files/PowerShell/7/pwsh.exe",
          kind: "pwsh",
        },
      },
    );
    expect(html).toContain('data-testid="canvas-section-script"');
    expect(html).toContain('data-testid="canvas-script-body"');
    expect(html).toContain("Write-Output hi");
    expect(html).toContain("out/a.txt");
    // 无 I18nProvider 回落英文键：冻结标注与「当前机将用」标注原样透出
    expect(html).toContain("frozen when the instance starts");
    expect(html).toContain("detected on this machine at run time");
    expect(html).toContain('data-testid="canvas-script-interpreter"');
    expect(html).toContain("pwsh.exe");
  });

  test("非脚本节点：分区显示「不适用」，不渲染正文", () => {
    const html = renderScript(
      { node: "实现", instance: "/p/i", card: { ...scriptCard }, executions: [] },
      { applicable: false },
    );
    expect(html).toContain('data-testid="canvas-section-script"');
    expect(html).toContain('data-testid="canvas-script-na"');
    expect(html).not.toContain('data-testid="canvas-script-body"');
    expect(html).not.toContain('data-testid="canvas-script-interpreter"');
  });

  test("脚本节点但探测失败：显示「未检测到」", () => {
    const html = renderScript(
      {
        node: "跑脚本",
        instance: "/p/i",
        card: { ...scriptCard, script: "Write-Output hi" },
        executions: [],
      },
      { applicable: true, interpreter: { available: false, reason: "未装" } },
    );
    expect(html).toContain('data-testid="canvas-script-interpreter-missing"');
    expect(html).toContain("No PowerShell interpreter detected");
  });

  test("脚本分区顺序在「输入与输出」之后、「回执轮次」之前", () => {
    const html = renderScript(
      {
        node: "跑脚本",
        instance: "/p/i",
        card: { ...scriptCard, script: "x" },
        executions: [],
      },
      { applicable: true },
    );
    expect(html.indexOf('data-testid="canvas-section-io"')).toBeLessThan(
      html.indexOf('data-testid="canvas-section-script"'),
    );
    expect(html.indexOf('data-testid="canvas-section-script"')).toBeLessThan(
      html.indexOf('data-testid="canvas-section-receipts"'),
    );
  });
});

import { expect, test } from "@playwright/test";
import type { PaoDesktopFlow, PaoDesktopFlowControlModule } from "@pao/sdk-driver";
import {
  WORKFLOW_CONTROL_ACTION_LABELS,
  WORKFLOW_CONTROL_ACTIONS,
  workflowControlCanResume,
  type WorkflowControlCommandInput,
} from "../../contracts/workflow-control";
import {
  createFlowControlQuery,
  normalizeFlowControl,
} from "../../electron/platform/pao/flow-control-query";

interface RunCall {
  readonly sessionId: string;
  readonly project: string;
  readonly params: Record<string, unknown>;
}

function desktopFlow(control: Partial<PaoDesktopFlow["控制"]> = {}): PaoDesktopFlow {
  return {
    路径: "/project/.pao/工作流实例-安装.md",
    控制: {
      实例: "ins-1",
      owner: "session-owner",
      工作流: "安装",
      卡目录: "/project/.pao/卡",
      状态: "挂起",
      暂停: "等人工核查后再推进",
      节点: [{ 名字: "拆解", 轮次: 2 }],
      ...control,
    },
    进度: {
      工作流: "安装",
      状态: "挂起",
      新建卡: [],
      节点: [
        {
          名字: "拆解",
          轮次: 2,
          状态: "in_progress",
          人工确认: true,
          挂起: "等人工核查后再推进",
        },
      ],
    },
  };
}

function moduleWith(
  flows: readonly PaoDesktopFlow[],
  issues: readonly { readonly 路径: string; readonly 说明: string }[] = [],
  onRun?: (call: RunCall) => void,
  onRead?: () => void,
): PaoDesktopFlowControlModule {
  return {
    readDesktopFlows: async () => {
      onRead?.();
      return { 工作流: [...flows], 问题: [...issues] };
    },
    runDesktopFlowCommand: async (sessionId, project, params) => {
      onRun?.({ sessionId, project, params: { ...params } });
    },
  };
}

const baseCommand = {
  workspaceId: "ws-a",
  sessionId: "session-other",
  instanceId: "ins-1",
  nodeName: "拆解",
  round: 2,
} as const;

