test("normalizeFlowControl 透传内核统一停因投影，动作权限以内核为准", () => {
  const stop = {
    category: "manual_pause",
    authority: "owner",
    actions: ["resume"],
    reason: "等人工核查后再推进",
    identity: { instance: "ins-1", node: "拆解", round: 2, cardRef: "0007", attempt: 1 },
  } as const;
  const base = desktopFlow();
  const identity = normalizeFlowControl({
    ...base,
    进度: { ...base.进度, 停止: stop },
  });

  expect(identity.stop).toEqual({
    category: "manual_pause",
    authority: "owner",
    actions: ["resume"],
    reason: "等人工核查后再推进",
    node: "拆解",
    round: 2,
    cardRef: "0007",
    attempt: 1,
  });
  expect(workflowControlCanResume(identity)).toBe(true);

  const decision = normalizeFlowControl({
    ...base,
    进度: {
      ...base.进度,
      停止: {
        category: "decision",
        authority: "human",
        actions: ["rule"],
        reason: "等待人工裁定",
        pending: { channel: "人工", kind: "设计取舍" },
      },
    },
  });
  expect(decision.stop?.category).toBe("decision");
  expect(decision.stop?.channel).toBe("人工");
  expect(decision.stop?.kind).toBe("设计取舍");
  expect(workflowControlCanResume(decision)).toBe(false);
});

