/**
 * 批4 片 C：编辑器横幅（editingFromInstance）与无 identity 只读链（renderToString 直渲染）。
 * 断言：①editingFromInstance 非空→横幅文案出现；空→无横幅。
 *       ②identity=undefined→fieldset disabled、保存按钮 disabled、提示文案出现；
 *         identity 有值→可交互。
 */
import { createElement } from "react";
import { renderToString } from "react-dom/server";
import { beforeAll, describe, expect, test } from "@playwright/test";
import type { I18nProvider as I18nProviderType } from "../../src/i18n/react";
import type { WizardRecipeNode } from "../../contracts/workflow-wizard";
import type { WorkflowCatalogSnapshot } from "../../contracts/workflow-wizard";
import type { PiDesktopApi } from "../../contracts/ipc";
import type { WorkflowWizardIdentity } from "../../src/features/canvas/workflow-wizard";

/**
 * Playwright 的 babel transform 会把 .tsx 编到它自带的 playwright/jsx-runtime，
 * renderToString 无法消化；先把该模块换成真 react/jsx-runtime 再加载组件。
 * I18nProvider 与组件同链——顶层静态 import 会在换缓存前绑定 jsx-runtime，
 * 必须同样在换缓存后 require（与 RecipeCanvasEditor 同模式）。
 */
let RecipeCanvasEditor: (typeof import("../../src/features/canvas/recipe-canvas-editor"))["RecipeCanvasEditor"];
let I18nProvider: typeof I18nProviderType;
beforeAll(() => {
  const real = require("react/jsx-runtime") as Record<string, unknown>;
  require.cache[require.resolve("playwright/jsx-runtime")] = {
    id: "react/jsx-runtime",
    filename: require.resolve("react/jsx-runtime"),
    loaded: true,
    exports: real,
  } as never;
  ({ RecipeCanvasEditor } = require("../../src/features/canvas/recipe-canvas-editor") as {
    RecipeCanvasEditor: typeof RecipeCanvasEditor;
  });
  ({ I18nProvider } = require("../../src/i18n/react") as {
    I18nProvider: typeof I18nProvider;
  });
});

const catalog: WorkflowCatalogSnapshot = {
  state: "available",
  recipes: [],
  departments: ["工程"],
  skills: [],
  tiers: [],
  thinkingLevels: [],
  templates: [],
  errors: [],
};

const identity: WorkflowWizardIdentity = { sessionId: "sess-1", project: "proj-1" };

function node(name: string, patch: Partial<WizardRecipeNode> = {}): WizardRecipeNode {
  return { 名字: name, 部门: "工程", depends_on: [], 目标: "目标", 验收: "验收", ...patch };
}

function render(
  nodes: readonly WizardRecipeNode[],
  opts: {
    selected?: string;
    identity?: WorkflowWizardIdentity;
    editingFromInstance?: string;
  } = {},
): string {
  return renderToString(
    // 横幅等新增固定文案走 i18n：包 zh 语言 Provider，断言真实中文值而非英文键。
    createElement(
      I18nProvider,
      { language: "zh" },
      createElement(RecipeCanvasEditor, {
        api: {} as PiDesktopApi,
        entry: {
          name: "配方",
          revision: null,
          recipe: { 名字: "配方", 参数: [], 节点: nodes, 版本: 2 },
        },
        onSaved: () => undefined,
        onDirtyChange: () => undefined,
        catalog,
        identity: opts.identity,
        editingFromInstance: opts.editingFromInstance,
        initialSelectedElementId: opts.selected,
      }),
    ),
  );
}

