describe("批4 片 C：无 identity 只读", () => {
  test("identity=undefined 时 fieldset disabled、保存按钮 disabled、提示文案出现", () => {
    const html = render([node("开发")], {});
    expect(html).toContain("<fieldset disabled");
    // 保存按钮 disabled
    expect(html).toMatch(/<button[^>]*disabled[^>]*>[\s\S]*?保存[\s\S]*?<\/button>/);
    // 提示文案
    expect(html).toContain("请先在项目中建立主控会话");
  });

  test("identity 有值时 fieldset 未 disabled、保存按钮可交互", () => {
    const html = render([node("开发")], { identity });
    expect(html).not.toContain("<fieldset disabled");
    // 保存按钮未 disabled（dirty 时 disabled 是正常逻辑，此处检查不因 locked 而 disabled）
    // 找保存按钮：disabled 仅当 busy||!dirty，此处无 dirty 所以 disabled 是因为 !dirty
    // 关键断言：不因 !identity 导致额外的 disabled
    expect(html).not.toContain("请先在项目中建立主控会话");
  });

  test("无 identity 时所有草稿操作按钮 disabled", () => {
    const html = render([node("开发")], {});
    // 添加部门任务
    expect(html).toMatch(/<button[^>]*disabled[^>]*>[\s\S]*?添加部门任务[\s\S]*?<\/button>/);
    // 连线
    expect(html).toMatch(/<button[^>]*disabled[^>]*>[\s\S]*?连线[\s\S]*?<\/button>/);
    // 自动整理
    expect(html).toMatch(/<button[^>]*disabled[^>]*>[\s\S]*?自动整理[\s\S]*?<\/button>/);
    // 另存为输入框
    expect(html).toMatch(/<input[^>]*aria-label="另存为名称"[^>]*disabled/);
    // 另存为按钮
    expect(html).toMatch(/<button[^>]*disabled[^>]*>[\s\S]*?另存为[\s\S]*?<\/button>/);
  });

  test("有 identity 时无 identity 相关禁用", () => {
    const html = render([node("开发")], { identity });
    // 添加部门任务按钮不因 identity 缺失而 disabled（dirty 时才 disabled）
    const addBtn = html.match(/<button[^>]*>[\s\S]*?添加部门任务[\s\S]*?<\/button>/)?.[0] ?? "";
    expect(addBtn).not.toContain("disabled");
    // 连线按钮不因 identity 缺失而 disabled
    const linkBtn = html.match(/<button[^>]*>[\s\S]*?连线[\s\S]*?<\/button>/)?.[0] ?? "";
    expect(linkBtn).not.toContain("disabled");
