/**
 * 批 4 片 A 徽标字段：编辑器 nodes useMemo 把配方中文键映射进 CanvasNodeView，
 * canvasNodeBadges 由此产出徽标。此处复现该映射并断言徽标结果
 * （ReactFlow 节点在 renderToString 下不挂载，无法直渲染断言）。
 */
describe("批 4 徽标字段（配方 → CanvasNodeView → canvasNodeBadges）", () => {
  // 与 recipe-canvas-editor.tsx nodes useMemo 相同的映射。
  const viewOf = (recipe: WizardRecipeNode): CanvasNodeView => ({
    name: recipe.名字,
    dept: recipe.部门,
    dependsOn: recipe.depends_on ?? [],
    requiresConfirmation: recipe.人工确认 === true,
    ...(recipe.审核 === true ? { isReview: true } : {}),
    ...(recipe.只读 === true ? { readOnly: true } : {}),
    ...(typeof recipe.执行方式 === "string" && recipe.执行方式.trim()
      ? { executionMode: recipe.执行方式.trim() as CanvasNodeView["executionMode"] }
      : {}),
  });
  const ids = (recipe: WizardRecipeNode) =>
    canvasNodeBadges(viewOf(recipe)).map((badge) => badge.id);

  test("审核节点 → review 徽标；非审核无徽标", () => {
    expect(ids(node("审", { 审核: true }))).toEqual(["review"]);
    expect(ids(node("普"))).toEqual([]);
  });

  test("只读节点 → readonly 徽标；缺省与非 true 不挂", () => {
    expect(ids(node("读", { 只读: true }))).toEqual(["readonly"]);
    expect(ids(node("普"))).toEqual([]);
    expect(ids(node("假", { 只读: false }))).toEqual([]);
    expect(ids(node("串", { 只读: "true" }))).toEqual([]);
  });

  test("执行方式 直接/脚本 → direct/script 徽标；拆解与缺省不挂", () => {
    expect(ids(node("直", { 执行方式: "直接" }))).toEqual(["direct"]);
    expect(ids(node("脚", { 执行方式: "脚本" }))).toEqual(["script"]);
    expect(ids(node("拆", { 执行方式: "拆解" }))).toEqual([]);
    expect(ids(node("普"))).toEqual([]);
  });

  test("组合字段按定序产出多个徽标", () => {
    expect(ids(node("全", { 审核: true, 只读: true, 执行方式: "直接", 人工确认: true }))).toEqual([
      "review",
