    expect(positions["实现新版"]).toEqual({ x: 40, y: 90 });
    expect("开发" in positions).toBe(false);
    expect(positions["测试"]).toEqual({ x: 380, y: 90 });
  });

  test("重名报错且不改草稿；同名与空白为 no-op（保留原名）", () => {
