describe("切离脚本确认 resolvePendingModeApply（批3b-U：确认作用于记录节点）", () => {
  const nodes = [
    node("脚本节点", { 执行方式: "脚本", 脚本: "x", 超时: 30, 产物: ["a"] }),
    node("别节点", { 执行方式: "拆解", 只读: true, 审核: true }),
  ];

  test("确认补丁作用于 pending 记录的节点名，与当前选中无关", () => {
    // 回归：确认框曾用当前 selectedNode 打补丁——触发确认后切到另一节点再确认，
    // 会把清脚本/清只读的补丁误写进新节点。这里 pending 绑定「脚本节点」，
    // 即使选中已切到「别节点」，补丁也只算自「脚本节点」并作用于它。
    const apply = resolvePendingModeApply(nodes, { nodeName: "脚本节点", mode: "直接" });
    expect(apply.nodeName).toBe("脚本节点");
    expect(apply.patch?.执行方式).toBe("直接");
    expect(apply.patch?.脚本).toBeUndefined();
    expect(apply.patch?.超时).toBeUndefined();
    expect(apply.patch?.产物).toBeUndefined();
    // 「直接」还额外清 只读/审核/回边（补丁显式携带这些键）。
    for (const key of ["只读", "审核", "回边"] as const) {
      expect(key in (apply.patch ?? {})).toBe(true);
    }
  });

  test("pending 为 null 或记录节点已删/改名 → 空结果，不写草稿", () => {
    expect(resolvePendingModeApply(nodes, null)).toEqual({});
    expect(resolvePendingModeApply(nodes, { nodeName: "已删节点", mode: "直接" })).toEqual({});
  });

  test("mode 为空串按缺省（undefined）语义清理脚本字段", () => {
    const apply = resolvePendingModeApply(nodes, { nodeName: "脚本节点", mode: "" });
    expect(apply.patch?.执行方式).toBeUndefined();
    expect(apply.patch?.脚本).toBeUndefined();
    // 缺省按「拆解」语义：不额外清 审核/只读/回边。
    expect(apply.patch).not.toHaveProperty("审核");
    expect(apply.patch).not.toHaveProperty("只读");
  });
});

