  });

  test("ps1 别名同样识别", () => {
    const text = "```ps1\nGet-Item .\n```";
    expect(extractPowerShellCandidates(text)).toEqual(["Get-Item ."]);
  });

  test("多个块按出现顺序各成候选", () => {
