describe("planScriptCandidateApply", () => {
  test("节点不存在返回 nodeGone", () => {
    expect(planScriptCandidateApply([node("开发")], "不存在", "X")).toEqual({
      result: "nodeGone",
      patch: undefined,
    });
  });

  test("空节点列表返回 nodeGone", () => {
    expect(planScriptCandidateApply([], "开发", "X").result).toBe("nodeGone");
  });

  test("脚本节点无旧正文 → applied，补丁写脚本", () => {
    const plan = planScriptCandidateApply(
      [node("清理", { 执行方式: "脚本" })],
      "清理",
      "Write-Output 1",
    );
    expect(plan.result).toBe("applied");
    expect(plan.patch?.脚本).toBe("Write-Output 1");
  });

  test("脚本节点正文与候选相同 → applied（不算冲突）", () => {
    const plan = planScriptCandidateApply(
      [node("清理", { 执行方式: "脚本", 脚本: "Write-Output 1" })],
      "清理",
      "Write-Output 1",
    );
    expect(plan.result).toBe("applied");
  });

  test("脚本节点已有不同正文 → conflict，不给补丁", () => {
    const plan = planScriptCandidateApply(
      [node("清理", { 执行方式: "脚本", 脚本: "旧脚本" })],
      "清理",
      "新脚本",
    );
    expect(plan.result).toBe("conflict");
    expect(plan.patch).toBeUndefined();
  });

  test("force=true 跳过内部 conflict 判定：冲突场景直接返回 applied 补丁", () => {
    // 「替换为候选」全链路：canvas-page 外层判冲突后，force 必须一路透传到这里，
    // 否则二次 conflict 让冲突 UI 永远无法完成替换。
    const plan = planScriptCandidateApply(
      [node("清理", { 执行方式: "脚本", 脚本: "旧脚本" })],
      "清理",
      "新脚本",
      true,
    );
    expect(plan.result).toBe("applied");
    expect(plan.patch?.脚本).toBe("新脚本");
  });

  test("force=true 仍校验节点存在：不存在返回 nodeGone", () => {
    expect(planScriptCandidateApply([node("开发")], "不存在", "X", true).result).toBe("nodeGone");
  });

  test("非脚本节点 → applied 且补丁带切脚本的清理字段", () => {
    const plan = planScriptCandidateApply(
      [node("开发", { 执行方式: "直接", 只读: true, 审核: true })],
      "开发",
      "Write-Output 1",
    );
    expect(plan.result).toBe("applied");
    expect(plan.patch?.执行方式).toBe("脚本");
    expect(plan.patch?.脚本).toBe("Write-Output 1");
    // executionModePatch("脚本") 语义：清只读/审核/回边/工人数量。
    expect(plan.patch?.只读).toBeUndefined();
    expect(plan.patch?.审核).toBeUndefined();
    expect("只读" in (plan.patch ?? {})).toBe(true);
    expect("审核" in (plan.patch ?? {})).toBe(true);
  });

  test("只出补丁不动草稿：传入的节点数组不被改写", () => {
    const nodes = [node("清理", { 执行方式: "脚本", 脚本: "旧" })];
    planScriptCandidateApply(nodes, "清理", "旧"); // applied 分支
    planScriptCandidateApply(nodes, "清理", "新"); // conflict 分支
    expect(nodes[0]?.脚本).toBe("旧");
    expect(nodes[0]?.执行方式).toBe("脚本");
  });
});

