  test("守卫等价性探针：同批坏形状 IPC 层与桥层双拒（对象性守卫双在位）", async () => {
    // 两层共有的节点行/配方对象性守卫：同批坏形状必须双拒，防单侧漂移无报警。
    // 有意分层（S2 选项一）：IPC 骨架另验名字/参数，桥层不验（IPC 强桥弱），深度契约单源＝内核。
    const badShapes = [
      "非对象配方",
