      main.append(
        element("h2", "实际 Git 差异（按需读取）"),
        element("pre", JSON.stringify(diff, null, 2)),
      );
    // 卡列表：待处理＝清单项目未完成卡；结果与恢复＝当前项目全卡；任务＝部门详情态只列所选部门的卡。
