        ? view.待处理.projects
            .flatMap((project) => project.cards)
            .filter((card) => !DEAD_STATUSES.includes(card.frontmatter.status))
        : tab === "结果与恢复"
          ? data.cards
          : inDept
            ? data.cards.filter((card) => card.frontmatter.dept === selectedDept)
            : [];
