          ),
        );
      article.append(
        button(selected === card.path ? "收起详情" : "查看卡／执行详情", async () => {
          selected = selected === card.path ? undefined : card.path;
        }),
        button("打开卡正本", () => openFile(card.path)),
      );
      // 卡详情按需展开钻取：frontmatter 结构化摘要＋折叠原始 JSON；回执逐条行；执行映射＋worker 增量。
      if (selected === card.path) {
        article.append(
          element("h2", "原始要求与验收"),
          element(
            "p",
            `目标：${fm.goal}\n验收：${fm.acceptance}\n约束：${fm.constraints ?? "（未声明）"}\n输入：${
              fm.inputs?.length ? fm.inputs.join("；") : "（未声明）"
            }`,
            "kv",
          ),
          jsonFallback("frontmatter 原始 JSON", fm),
        );
        article.append(
          element("h2", "结果／证据／遗留"),
          element("pre", card.body || "暂无正文；未提供实际 diff 的任务不推断已完成。"),
        );
        article.append(element("h2", "回执"));
        if (!card.receipts.length) article.append(element("p", "暂无回执。", "muted"));
        for (const receipt of card.receipts) {
          article.append(
            element(
              "p",
              `回执 卡${receipt.card_no} · 尝试${receipt.attempt} · ${receipt.time}${
                receipt.result ? ` · ${receipt.result}` : ""
              }${receipt.failure_type ? ` · ${receipt.failure_type}` : ""}${
                receipt.archive_flag ? ` · ${receipt.archive_flag}` : ""
              }`,
              "kv",
            ),
          );
          if (receipt.summary) article.append(element("p", `摘要：${receipt.summary}`, "kv"));
        }
        article.append(
          element(
            "p",
            `恢复前摘要：${fm.status === "delivered" ? "卡面已交付；仍以验收证据为准" : fm.status === "in_progress" ? "需核对 owner 进程和执行映射，不能只凭卡面推断仍在运行" : fm.status === "failed" ? "上次失败／中断，可能有已改未验内容" : "尚待原 owner 明确决定下一步"}。拟续跑：未自动批准。`,
          ),
        );
        const executions = data.execution.filter((entry) => entry.卡路径 === card.path);
        if (!executions.length) article.append(element("p", "尚无可核对执行映射。"));
        for (const execution of executions) {
          article.append(
            element(
              "p",
              `执行 ${execution.执行标识} · 尝试${execution.尝试} · ${execution.状态} · ${execution.当前尝试 ? "当前" : "历史"}`,
            ),
          );
          article.append(button("读取 worker 增量", () => readMore(execution.执行标识)));
        }
      }
      main.append(article);
    }
    if (executionId) {
      main.append(
        element("h2", `worker 会话 · ${executionId}`),
        element("p", streamStatus, "muted"),
      );
      if (lines.length) {
        // 行列表替代整块 JSON dump：等宽小字逐行，容器限高滚动；截断逻辑见 readMore（最近 500 行）。
        const box = element("div", undefined, "log-box");
        for (const line of lines) box.append(element("div", workerLineText(line), "log-line"));
        main.append(box);
      } else main.append(element("p", "尚未读到内容；点上方「钻取／读取增量」继续。", "muted"));
      if (sessionPath) main.append(button("打开完整会话原文", () => openFile(sessionPath)));
    }
  }
  const dispose = () => {
    disposed = true;
    if (autoRefreshTimer !== undefined) {
      clearTimeout(autoRefreshTimer);
      autoRefreshTimer = undefined;
    }
    host.signal.removeEventListener("abort", dispose);
    binding
      .dispose(BACKGROUND_CONTEXT)
      .catch((reason) => console.error("PAO 视图连接释放失败", reason));
    root.replaceChildren();
  };
  host.signal.addEventListener("abort", dispose, { once: true });
  await binding.ready(BACKGROUND_CONTEXT);
  host.signal.throwIfAborted();
  await perform(refresh);
  // 首屏总览就要带配置摘要（档位/技能数/问题数），所以目录跟首刷一起拉；
  // 失败只落 deptError，不影响卡会话那一半照常显示。
  await perform(loadDeptCatalog);
  return dispose;
}

import assert from "node:assert/strict";
import { mkdir, mkdtemp, realpath, rm, writeFile } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";
import test, { after } from "node:test";
import { fauxAssistantMessage, fauxProvider, type Context } from "@pao/ai";
import { ModelRuntime, createAgentSession, type AgentSession } from "@pao/coding-agent";
import type { SessionRef } from "@pao/session-driver";
import { SideChatSupervisor } from "./dist/side-chat.js";
import type { SessionSupervisor, SideChatSourceSnapshot } from "./dist/session-supervisor.js";

const roots: string[] = [];

after(async () => {
  await Promise.all(roots.map((root) => rm(root, { recursive: true, force: true })));
});

async function makeRoot(): Promise<{ agentDir: string; workspace: string }> {
  const root = await mkdtemp(join(tmpdir(), "p4-side-chat-probe-"));
  roots.push(root);
  const agentDir = join(root, "agent");
  const workspace = join(root, "workspace");
  await mkdir(agentDir);
  await mkdir(workspace);
  await writeFile(join(agentDir, "auth.json"), "{}");
  await writeFile(join(agentDir, "settings.json"), JSON.stringify({ packages: [] }));
  await writeFile(join(agentDir, "models.json"), JSON.stringify({ providers: {} }));
  return { agentDir, workspace };
}

function textOf(content: unknown): string {
  if (typeof content === "string") return content;
  if (!Array.isArray(content)) return "";
  return content
    .flatMap((part) =>
      typeof part === "object" &&
      part !== null &&
      "type" in part &&
      part.type === "text" &&
      "text" in part &&
      typeof part.text === "string"
        ? [part.text]
        : [],
    )
    .join("\n");
}

test("failed partial response is persisted as complete", async () => {
  const { agentDir, workspace } = await makeRoot();
  const ref: SessionRef = { workspaceId: "probe-workspace", sessionId: "probe-session" };
  const fakeSession = {
    messages: [] as unknown[],
    getActiveToolNames: () => ["read"],
    getCallableToolNames: () => ["read"],
    async prompt() {
      this.messages.push({
        role: "assistant",
        content: [{ type: "text", text: "PARTIAL_ANSWER_SAVED_AS_SUCCESS" }],
        api: "faux",
        provider: "faux",
        model: "probe",
        usage: {
          input: 0,
          output: 0,
          cacheRead: 0,
          cacheWrite: 0,
          totalTokens: 0,
          cost: { input: 0, output: 0, cacheRead: 0, cacheWrite: 0, total: 0 },
        },
        stopReason: "error",
        errorMessage: "PROVIDER_FAILED_AFTER_PARTIAL",
        timestamp: Date.now(),
      });
    },
  };
  const source: SideChatSourceSnapshot = {
    ref,
    workspacePath: workspace,
    status: "idle",
    boundaryId: "leaf-probe",
    capturedAt: new Date().toISOString(),
    sourceBusy: false,
    messages: [],
    modelRuntime: {} as SideChatSourceSnapshot["modelRuntime"],
    modelSelection: { provider: "faux", modelId: "probe" },
    limitations: [],
  };
  const supervisor = new SideChatSupervisor({
    supervisor: {} as SessionSupervisor,
    agentDir,
    createSideChatSource: async () => source,
    runtimeFactory: async () => ({
      session: fakeSession as unknown as AgentSession,
      dispose() {},
    }),
  });

  const snapshot = await supervisor.sendSideChatMessage({
    source: ref,
    text: "PROBE_FAILED_QUESTION",
  });
  const message = snapshot.messages.find(
    (item) => item.role === "assistant" && item.text === "PARTIAL_ANSWER_SAVED_AS_SUCCESS",
  );
  assert.ok(message);
  console.log(
    JSON.stringify({
      probe: "failed_partial",
      status: message.status,
      hasError: Boolean(message.error),
      snapshotError: snapshot.error ?? null,
    }),
  );
  assert.equal(message.status, "complete");
  assert.equal(message.error, undefined);
  assert.equal(snapshot.error, undefined);
});

test("invalid image is omitted while contextComplete remains true", async () => {
  const { agentDir, workspace } = await makeRoot();
  const workspaceRealPath = await realpath(workspace);
  const ref: SessionRef = { workspaceId: "probe-workspace", sessionId: "probe-image-session" };
  const faux = fauxProvider({ models: [{ id: "probe-image-model", input: ["text", "image"] }] });
  const contexts: Context[] = [];
  const response = (context: Context) => {
    contexts.push(context);
    return fauxAssistantMessage("IMAGE_PROBE_ANSWER");
  };
  faux.setResponses([response, response, response, response]);
  const modelRuntime = await ModelRuntime.create({
    modelsPath: join(agentDir, "models.json"),
    authPath: join(agentDir, "auth.json"),
    refreshOnCreate: false,
  });
  const model = faux.getModel();
  modelRuntime.registerNativeProvider(faux.provider);
  const source: SideChatSourceSnapshot = {
    ref,
    workspacePath: workspace,
    status: "idle",
    boundaryId: "leaf-image",
    capturedAt: new Date().toISOString(),
    sourceBusy: false,
    messages: [
      {
        role: "user",
        content: [
          { type: "text", text: "SOURCE_HAS_INVALID_IMAGE" },
          { type: "image", data: "bm90LWEtcG5n", mimeType: "image/tiff" },
        ],
        timestamp: Date.now(),
      },
    ],
    modelRuntime,
    modelSelection: { provider: model.provider, modelId: model.id },
    limitations: [],
  };
  const supervisor = new SideChatSupervisor({
    supervisor: {} as SessionSupervisor,
    agentDir,
    createSideChatSource: async () => source,
    runtimeFactory: async ({ manager }) => {
      const created = await createAgentSession({
        cwd: workspaceRealPath,
        agentDir,
        modelRuntime,
        model,
        sessionManager: manager,
        tools: [],
      });
      return {
        session: created.session,
        dispose: () => created.session.dispose(),
      };
    },
  });

  const snapshot = await supervisor.sendSideChatMessage({
    source: ref,
    text: "PROBE_BAD_IMAGE",
  });
  const context = contexts.find((item) =>
    item.messages.some((message) => textOf(message.content).includes("PROBE_BAD_IMAGE")),
  );
  assert.ok(context);
  const contextText = context.messages.map((message) => textOf(message.content)).join("\n");
  const actualImages = context.messages.reduce(
    (count, message) =>
      count +
      (Array.isArray(message.content)
        ? message.content.filter((part) => part.type === "image").length
        : 0),
    0,
  );
  console.log(
    JSON.stringify({
      probe: "invalid_image",
      contextComplete: snapshot.sync.contextComplete,
      limitations: snapshot.sync.limitations,
      actualImages,
      omittedHint: contextText.includes("[Image omitted"),
    }),
  );
  assert.equal(snapshot.sync.contextComplete, true);
  assert.equal(actualImages, 0);
  assert.equal(contextText.includes("[Image omitted"), true);
});

