      requestCleanup: unexpected,
    },
  };
  return {
    agentDir,
    workspace: { workspaceId: "pao-inventory", path: workspacePath },
    paoExtensionOptions,
    inspect,
    inventory: () => {
      assert.ok(loaded, "应经过真实资源加载器");
      return loaded;
    },
  };
}

