      failedAnswer?.error?.message ?? "",
      new RegExp(`P4_${stopReason.toUpperCase()}_FAILED`),
    );

    app.faux.setResponses([
      (context) => {
        app.contexts.push(context);
        return fauxAssistantMessage("P4_RECOVERY_COMPLETE");
      },
    ]);
